const standorte = [{ id: "fenster_sued", name: "Südfenster" }];
const pflanzen = [{ id: "basilikum_1", name: "Basilikum", standortId: "fenster_sued", feuchteGrenzwert: 35 }];

function pflanzenAmStandort(standortId) {
  return pflanzen.filter((pflanze) => pflanze.standortId === standortId);
}

// Lernbeispiel: API an das verwendete ESP32-Framework anpassen.
struct Einstellungen {
  int formatVersion = 1;
  int feuchteGrenzwert = 35;
  int messintervallSekunden = 60;
};

bool istGueltig(const Einstellungen& wert) {
  return wert.formatVersion == 1
    && wert.feuchteGrenzwert >= 0 && wert.feuchteGrenzwert <= 100
    && wert.messintervallSekunden >= 10;
}

// Lernbeispiel: begrenztes Journal statt unbegrenzter Historie.
struct Messwert {
  long zeitstempel;
  int bodenfeuchteProzent;
};

constexpr size_t MAX_EINTRAEGE = 120;
// Aufgabe: als JSON Lines oder CSV schreiben, gültige Zeilen lesen
// und bei MAX_EINTRAEGE die ältesten Einträge kontrolliert ersetzen.

PRAGMA foreign_keys = ON;

CREATE TABLE standorte (
  standort_id TEXT PRIMARY KEY,
  name TEXT NOT NULL
);

CREATE TABLE pflanzen (
  pflanze_id TEXT PRIMARY KEY,
  standort_id TEXT NOT NULL REFERENCES standorte(standort_id),
  name TEXT NOT NULL,
  feuchte_grenzwert INTEGER NOT NULL CHECK (feuchte_grenzwert BETWEEN 0 AND 100)
);

CREATE TABLE messungen (
  messung_id INTEGER PRIMARY KEY,
  pflanze_id TEXT NOT NULL REFERENCES pflanzen(pflanze_id),
  gemessen_am TEXT NOT NULL,
  bodenfeuchte_prozent INTEGER NOT NULL CHECK (bodenfeuchte_prozent BETWEEN 0 AND 100)
);

CREATE INDEX idx_messungen_pflanze_zeit ON messungen(pflanze_id, gemessen_am);
